import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        String s = next();
        int n = s.length();
        boolean sorted = true;
        char lo = 'z', hi = 'a';
        int loCount = 0, hiCount = 0;
        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            if (i > 0 && s.charAt(i - 1) > c) sorted = false;
            lo = (char) Math.min(lo, c);
            hi = (char) Math.max(hi, c);
        }
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == lo) loCount++;
            if (s.charAt(i) == hi) hiCount++;
        }
        int answer;
        if (sorted) answer = 0;
        else if (s.charAt(0) == lo || s.charAt(n - 1) == hi) answer = 1; // sort everything but the correct end
        else if (s.charAt(0) == hi && s.charAt(n - 1) == lo && loCount == 1 && hiCount == 1)
            answer = 3; // unique max first and unique min last: no single step fixes an end
        else answer = 2;
        System.out.println(answer);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	s := token()
	n := len(s)
	sorted := true
	lo, hi := byte('z'), byte('a')
	for i, c := range s {
		if i > 0 && s[i-1] > c {
			sorted = false
		}
		lo, hi = min(lo, c), max(hi, c)
	}
	loCount, hiCount := 0, 0
	for _, c := range s {
		if c == lo {
			loCount++
		}
		if c == hi {
			hiCount++
		}
	}
	answer := 2
	if sorted {
		answer = 0
	} else if s[0] == lo || s[n-1] == hi {
		answer = 1 // sort everything but the correct end
	} else if s[0] == hi && s[n-1] == lo && loCount == 1 && hiCount == 1 {
		answer = 3 // unique max first and unique min last: no single step fixes an end
	}
	fmt.Println(answer)
}
